"""budget_guard.py -- a step cap and a budget cap for a retry loop.

Offline demo: python budget_guard.py
"""
from dataclasses import dataclass


class BudgetExceeded(RuntimeError):
  """Raised when one more step would cross the step cap or the cost cap."""


@dataclass
class BudgetGuard:
  max_steps: int
  max_cost_usd: float
  steps: int = 0
  spent_usd: float = 0.0

  def record(self, step_cost_usd: float) -> None:
    if self.steps + 1 > self.max_steps:
      raise BudgetExceeded(
        f"stopped after {self.steps} steps: the cap is {self.max_steps}"
      )
    if self.spent_usd + step_cost_usd > self.max_cost_usd:
      raise BudgetExceeded(
        f"stopped after {self.steps} steps: spending "
        f"${self.spent_usd + step_cost_usd:.3f} would cross the "
        f"${self.max_cost_usd:.3f} cap"
      )
    self.steps += 1
    self.spent_usd += step_cost_usd


def call_model_that_keeps_failing(guard: BudgetGuard) -> None:
  """Stands in for a real call: every attempt fails validation, so a plain
  retry-on-failure loop would otherwise never stop on its own."""
  guard.record(step_cost_usd=0.004)
  raise ValueError("output failed schema validation")


def run_with_retries() -> None:
  guard = BudgetGuard(max_steps=6, max_cost_usd=0.05)
  while True:
    try:
      call_model_that_keeps_failing(guard)
    except BudgetExceeded as stopped:
      print(f"guard stopped the loop: {stopped}")
      return
    except ValueError:
      continue  # the bug on its own: retry-on-failure with no cap


if __name__ == "__main__":
  run_with_retries()
